function getRows(items) {
  if (!items?.length) return [];
  const raw = items[0].json;
  if (Array.isArray(raw)) return raw;
  if (raw?.data && Array.isArray(raw.data)) return raw.data;
  if (raw?.content) {
    const t = raw.content.find(c => c.type === 'text');
    if (t?.text) {
      try {
        const p = JSON.parse(t.text);
        return Array.isArray(p) ? p : (p.data || p.rows || []);
      } catch(e) { return []; }
    }
  }
  return raw?.result || [];
}

const rows = getRows($input.all());

const undervalued = rows
  .filter(r => r.pb_mrq > 0 && r.daily_close_change < 0)
  .sort((a, b) => a.pb_mrq - b.pb_mrq)
  .slice(0, 10)
  .map((r, i) => ({
    no: i + 1,
    emiten: r.symbol,
    pbv: Number(r.pb_mrq.toFixed(2)),
    harga: r.last_close_price,
    perubahan_harga: `${(r.daily_close_change * 100).toFixed(2)}%`
  }));

return [{ json: { category: 'undervalued', data: undervalued } }];

