const rows = getRows($input.all());

const cashflow = rows
  .filter(r => r.operating_cash_flow != null)
  .sort((a, b) => b.operating_cash_flow - a.operating_cash_flow)
  .slice(0, 10)
  .map((r, i) => ({
    no: i + 1,
    emiten: r.symbol,
    arus_kas_operasional: r.operating_cash_flow,
    arus_kas_investasi: r.investing_cash_flow,
    arus_kas_pendanaan: r.financing_cash_flow
  }));

const topRoa = rows
  .filter(r => r.roa_ttm != null)
  .sort((a, b) => b.roa_ttm - a.roa_ttm)
  .slice(0, 10)
  .map((r, i) => ({ no: i + 1, emiten: r.symbol, roa: `${(r.roa_ttm * 100).toFixed(1)}%` }));

const topRoe = rows
  .filter(r => r.roe_ttm != null)
  .sort((a, b) => b.roe_ttm - a.roe_ttm)
  .slice(0, 10)
  .map((r, i) => ({ no: i + 1, emiten: r.symbol, roe: `${(r.roe_ttm * 100).toFixed(1)}%` }));

return [{ json: { category: 'fundamentals', cashflow, top_roa: topRoa, top_roe: topRoe } }];

const undervalued = $('A1 Process Undervalued').first().json.data || [];
const valueStock = $('A2 Process Value Stock').first().json.data || [];
const fundamentals = $('A3 Process Fundamentals').first().json || {};

const tanggal = new Date().toLocaleDateString('id-ID', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

let msg = `📊 *PRE-MARKET BRIEFING* — ${tanggal}\n\n`;

msg += `*🔻 Undervalued (PBV Rendah, Harga Turun)*\n`;
if (undervalued.length > 0) {
  undervalued.forEach(r => {
    msg += `${r.no}. ${r.emiten.replace(/[_*`\[]/g, '\\$&')} — PBV ${r.pbv} | Rp${r.harga.toLocaleString('id-ID')} (${r.perubahan_harga})\n`;
  });
} else {
  msg += `Tidak ada data\n`;
}

msg += `\n*💎 Value Stock (Fundamental Bagus, Harga Diskon)*\n`;
if (valueStock.length > 0) {
  valueStock.forEach(r => {
    msg += `${r.no}. ${r.emiten.replace(/[_*`\[]/g, '\\$&')} — ROE ${r.roe} | Rp${r.harga.toLocaleString('id-ID')}\n`;
  });
} else {
  msg += `Tidak ada data\n`;
}

msg += `\n*🏆 Top ROE*\n`;
if (fundamentals.top_roe && fundamentals.top_roe.length > 0) {
  fundamentals.top_roe.forEach(r => { 
    msg += `${r.no}. ${r.emiten} — ${r.roe}\n`; 
  });
} else {
  msg += `Tidak ada data\n`;
}

msg += `\n_Data: Sectors API • Otomatis via n8n • Bukan rekomendasi beli/jual_`;

return [{ json: { telegram_message: msg } }];

const telegramMessage = $('A4 Format Telegram').first().json.telegram_message;
const apiResponse = $input.first().json;
const subscribers = Array.isArray(apiResponse) ? apiResponse : [];

if (subscribers.length === 0) {
  throw new Error('No active subscribers found');
}

return subscribers.map(sub => ({
  json: {
    telegram_chat_id: sub.telegram_chat_id,
    telegram_message: telegramMessage,
    user_id: sub.user_id
  }
}));
